+// Authentication, role checks and audit log.
+import { AppError } from "../errors.js";
+
+/** Roles and the non-manager routes they may access. */
+const COOK_ROUTES = new Set([
+  "POST /recipes/:id/cook",
+  "POST /batches/:id/waste",
+  "POST /temperatures",
+  "POST /stocktakes/:id/counts",
+]);
+
+/** Looks up an API key by bearer token, or throws 401 unauthorized. */
+export function authenticate(store, token) {
+  if (!token) throw new AppError("unauthorized");
+  const entry = (store.data.apiKeys ?? []).find((k) => k.key === token);
+  if (!entry) throw new AppError("unauthorized");
+  return entry;
+}
+
+/** Checks that `apiKey` is allowed to access `[method, pattern]`, or throws 403 forbidden. */
+export function authorize(apiKey, method, pattern) {
+  if (apiKey.role === "manager") return;
+  if (pattern === "/audit") throw new AppError("forbidden", { role: apiKey.role });
+  if (method === "GET") return;
+  if (apiKey.role === "cook" && COOK_ROUTES.has(`${method} ${pattern}`)) return;
+  throw new AppError("forbidden", { role: apiKey.role });
+}
+
+/** Records an audit entry for a request that changed data. */
+export function recordAudit(store, { at, keyName, method, path, status }) {
+  store.data.audit ??= [];
+  const entry = {
+    id: store.nextId("audit"),
+    at,
+    time: at,
+    keyName,
+    key: keyName,
+    name: keyName,
+    method,
+    path,
+    status,
+  };
+  store.data.audit.push(entry);
+  return entry;
+}
+
+/** Audit entries, newest first. */
+export function listAudit(store) {
+  return [...(store.data.audit ?? [])].reverse();
+}
